  const [formData, setFormData] = useState({
    event_name: '',
    event_date: '',
    location: '',
    brief: ''
  });

  const handleSubmit = async () => {
    if (!formData.event_name || bag.length === 0) {
      return alert("Please provide event details and select at least one talent.");
