    setLoading(true);
    try {
      const data = {
        ...formData,
        talent_names: bag.map(t => t.name).join(', '),
        status: 'pending'
      };
      const { error } = await supabase.from('event_requests').insert([data]);
      if (error) throw error;
      alert("Unified Request Sent to LYNQUP Engine!");
      onSuccess();
    } catch (err: any) {
      alert(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="bg-white min-h-screen text-black pb-20 pt-24">
      <main className="max-w-7xl mx-auto px-6 pt-10">
