import React, { useRef, useState, useMemo } from 'react';
import { Canvas, useFrame, useThree } from '@react-three/fiber';
import * as THREE from 'three';
import { motion } from 'framer-motion-3d';

const Mascot = () => {
  const headRef = useRef<THREE.Group>(null!);
  const leftEyeRef = useRef<THREE.Mesh>(null!);
  const rightEyeRef = useRef<THREE.Mesh>(null!);
  const { mouse, viewport } = useThree();
  const [blink, setBlink] = useState(false);

  // Random blinking logic
  useFrame((state) => {
    const t = state.clock.getElapsedTime();

    // Floating movement
    headRef.current.position.y = Math.sin(t * 2) * 0.15;

    // Head tracking pointer
    // We map mouse (-1 to 1) to head rotation
    const targetRotationX = -mouse.y * 0.5;
    const targetRotationY = mouse.x * 0.5;

    headRef.current.rotation.x = THREE.MathUtils.lerp(headRef.current.rotation.x, targetRotationX, 0.1);
    headRef.current.rotation.y = THREE.MathUtils.lerp(headRef.current.rotation.y, targetRotationY, 0.1);

    // Eye tracking (subtle extra movement)
    if (leftEyeRef.current && rightEyeRef.current) {
      const eyeLookX = mouse.x * 0.1;
      const eyeLookY = -mouse.y * 0.1;
      leftEyeRef.current.position.x = -0.3 + eyeLookX;
      leftEyeRef.current.position.y = 0.1 + eyeLookY;
      rightEyeRef.current.position.x = 0.3 + eyeLookX;
      rightEyeRef.current.position.y = 0.1 + eyeLookY;
    }

    // Blinking trigger
    if (Math.random() < 0.01 && !blink) {
      setBlink(true);
      setTimeout(() => setBlink(false), 150);
    }
  });

  return (
    <group ref={headRef}>
      {/* Main Head Shell */}
      <mesh>
        <sphereGeometry args={[1, 32, 32]} />
        <meshStandardMaterial 
          color="#ffffff" 
          roughness={0.1} 
          metalness={0.8} 
          envMapIntensity={1}
        />
      </mesh>

      {/* Visor Area */}
      <mesh position={[0, 0, 0.4]} scale={[1.1, 0.6, 0.8]}>
        <sphereGeometry args={[0.8, 32, 32]} />
        <meshStandardMaterial color="#111111" roughness={0} />
      </mesh>

      {/* Digital Eyes */}
      <mesh ref={leftEyeRef} position={[-0.3, 0.1, 0.85]} scale={[1, blink ? 0.1 : 1, 1]}>
        <planeGeometry args={[0.2, 0.2]} />
        <meshBasicMaterial color="#0071e3" transparent opacity={0.9} />
      </mesh>
      <mesh ref={rightEyeRef} position={[0.3, 0.1, 0.85]} scale={[1, blink ? 0.1 : 1, 1]}>
        <planeGeometry args={[0.2, 0.2]} />
        <meshBasicMaterial color="#0071e3" transparent opacity={0.9} />
      </mesh>

      {/* Floating Ring / Antenna Halo */}
      <mesh rotation={[Math.PI / 2, 0, 0]} position={[0, 1.2, 0]}>
        <torusGeometry args={[0.4, 0.02, 16, 100]} />
        <meshBasicMaterial color="#0071e3" />
      </mesh>

      {/* Dynamic Lighting for the head */}
      <pointLight position={[2, 2, 2]} intensity={1} color="#0071e3" />
    </group>
  );
};

const PointerAvatar: React.FC = () => {
  return (
    <div className="fixed bottom-8 right-8 w-40 h-40 z-[150] pointer-events-none cursor-grab active:cursor-grabbing">
      <Canvas camera={{ position: [0, 0, 5], fov: 45 }}>
