  useFrame((state) => {
    const t = state.clock.getElapsedTime();

    // Smooth Floating
    headRef.current.position.y = Math.sin(t * 1.5) * 0.1;

    // Advanced Head Tracking
    const targetRotX = -mouse.y * 0.4;
    const targetRotY = mouse.x * 0.5;
