        </mesh>
        {/* The Bun */}
        <mesh position={[0, 1.1, -0.4]}>
          <sphereGeometry args={[0.5, 32, 32]} />
          <primitive object={hairMat} attach="material" />
        </mesh>
        {/* Decorative Tech Ring on Bun */}
        <mesh position={[0, 1.1, -0.4]} rotation={[Math.PI / 2, 0, 0]}>
          <torusGeometry args={[0.55, 0.03, 16, 100]} />
          <meshBasicMaterial color="#0071e3" />
        </mesh>
      </group>

      {/* Eyes Container */}
