import React, { useRef, useState, useMemo } from 'react';
import { Canvas, useFrame, useThree } from '@react-three/fiber';
import * as THREE from 'three';

const AetherCompanion = () => {
  const groupRef = useRef<THREE.Group>(null!);
  const bodyRef = useRef<THREE.Mesh>(null!);
  const leftHandRef = useRef<THREE.Mesh>(null!);
  const rightHandRef = useRef<THREE.Mesh>(null!);
  const leftEyeRef = useRef<THREE.Mesh>(null!);
  const rightEyeRef = useRef<THREE.Mesh>(null!);

  const { mouse } = useThree();
  const [blink, setBlink] = useState(false);

  // Materials
  const bodyMaterial = useMemo(() => new THREE.MeshPhysicalMaterial({
    color: "#ffffff",
    metalness: 0,
    roughness: 0.1,
    transmission: 0.6, // Glass-like
    thickness: 0.5,
    ior: 1.5,
    clearcoat: 1,
    clearcoatRoughness: 0.1,
    transparent: true,
    opacity: 0.9,
  }), []);

  const coreMaterial = useMemo(() => new THREE.MeshStandardMaterial({
    color: "#0071e3",
    emissive: "#0071e3",
    emissiveIntensity: 2,
  }), []);

  const eyeMaterial = useMemo(() => new THREE.MeshStandardMaterial({
    color: "#ffffff",
    emissive: "#ffffff",
    emissiveIntensity: 5,
  }), []);

  useFrame((state) => {
    const t = state.clock.getElapsedTime();

    // 1. Idle Breathing & Floating
    const scale = 1 + Math.sin(t * 2) * 0.03;
    bodyRef.current.scale.set(scale, scale, scale);
    groupRef.current.position.y = Math.sin(t * 1.5) * 0.15;

    // 2. Responsive Head Tilt & Gaze
    const targetRotX = -mouse.y * 0.4;
    const targetRotY = mouse.x * 0.5;
    groupRef.current.rotation.x = THREE.MathUtils.lerp(groupRef.current.rotation.x, targetRotX, 0.1);
    groupRef.current.rotation.y = THREE.MathUtils.lerp(groupRef.current.rotation.y, targetRotY, 0.1);

    // 3. Trailing Satellites (Hands)
    if (leftHandRef.current && rightHandRef.current) {
      // Left hand orbits and trails
      const lx = -1.2 + Math.cos(t * 0.5) * 0.1;
      const ly = Math.sin(t * 2) * 0.1;
      const lz = Math.sin(t * 0.5) * 0.2;
      leftHandRef.current.position.x = THREE.MathUtils.lerp(leftHandRef.current.position.x, lx - mouse.x * 0.5, 0.05);
      leftHandRef.current.position.y = THREE.MathUtils.lerp(leftHandRef.current.position.y, ly - mouse.y * 0.5, 0.05);
      leftHandRef.current.position.z = lz;

      // Right hand orbits and trails
      const rx = 1.2 + Math.sin(t * 0.5) * 0.1;
      const ry = Math.cos(t * 2) * 0.1;
      const rz = Math.cos(t * 0.5) * 0.2;
      rightHandRef.current.position.x = THREE.MathUtils.lerp(rightHandRef.current.position.x, rx - mouse.x * 0.5, 0.05);
      rightHandRef.current.position.y = THREE.MathUtils.lerp(rightHandRef.current.position.y, ry - mouse.y * 0.5, 0.05);
      rightHandRef.current.position.z = rz;
    }

    // 4. Eye Interaction
    if (leftEyeRef.current && rightEyeRef.current) {
      const eyeScaleY = blink ? 0.05 : 1 + Math.abs(mouse.y) * 0.2;
      leftEyeRef.current.scale.y = THREE.MathUtils.lerp(leftEyeRef.current.scale.y, eyeScaleY, 0.2);
      rightEyeRef.current.scale.y = THREE.MathUtils.lerp(rightEyeRef.current.scale.y, eyeScaleY, 0.2);
    }

    // Random Blink
    if (Math.random() < 0.008 && !blink) {
      setBlink(true);
      setTimeout(() => setBlink(false), 150);
    }
  });

  return (
    <group ref={groupRef}>
      {/* Internal Core (The "Spirit") */}
      <mesh position={[0, 0, 0]}>
        <sphereGeometry args={[0.4, 32, 32]} />
        <primitive object={coreMaterial} attach="material" />
      </mesh>

      {/* Main Frosted Body */}
      <mesh ref={bodyRef}>
        <sphereGeometry args={[1, 64, 64]} />
        <primitive object={bodyMaterial} attach="material" />
      </mesh>

      {/* Visor Area (Subtle Dark Strip) */}
      <mesh position={[0, 0.1, 0.8]} scale={[1, 0.25, 1]}>
        <sphereGeometry args={[0.22, 32, 32]} />
        <meshStandardMaterial color="#000000" roughness={0.1} transparent opacity={0.4} />
      </mesh>

      {/* Digital Eyes */}
      <group position={[0, 0.1, 0.98]}>
        <mesh ref={leftEyeRef} position={[-0.15, 0, 0]}>
          <capsuleGeometry args={[0.03, 0.06, 4, 8]} />
          <primitive object={eyeMaterial} attach="material" />
        </mesh>
        <mesh ref={rightEyeRef} position={[0.15, 0, 0]}>
          <capsuleGeometry args={[0.03, 0.06, 4, 8]} />
          <primitive object={eyeMaterial} attach="material" />
        </mesh>
      </group>

      {/* Satellite Hands */}
      <mesh ref={leftHandRef} position={[-1.2, 0, 0]}>
        <sphereGeometry args={[0.12, 32, 32]} />
        <primitive object={bodyMaterial} attach="material" />
      </mesh>
      <mesh ref={rightHandRef} position={[1.2, 0, 0]}>
        <sphereGeometry args={[0.12, 32, 32]} />
        <primitive object={bodyMaterial} attach="material" />
      </mesh>

      {/* Ambient Glow */}
      <pointLight position={[0, 0, 0]} intensity={2} color="#0071e3" distance={5} />
    </group>
  );
};

const PointerAvatar: React.FC = () => {
  return (
    <div className="fixed bottom-0 right-0 w-[320px] h-[320px] z-[150] pointer-events-none">
      <Canvas camera={{ position: [0, 0, 5], fov: 35 }} alpha={true}>
        <ambientLight intensity={0.8} />
        <spotLight position={[10, 10, 10]} angle={0.15} penumbra={1} intensity={1.5} />
        <pointLight position={[-5, -5, -5]} color="#0071e3" intensity={0.5} />
        <AetherCompanion />
