  onClose: () => void;
  isThinking: boolean;
  setIsThinking: (v: boolean) => void;
}

const HelpBot: React.FC<HelpBotProps> = ({ isOpen, onClose, isThinking, setIsThinking }) => {
  const [messages, setMessages] = useState<{role: 'user' | 'bot', text: string}[]>([
    { role: 'bot', text: "Protocol initialized. I am LynqSwift. How can I assist your execution today?" }
  ]);
  const [input, setInput] = useState('');
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || isThinking) return;

    const userMsg = input.trim();
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setIsThinking(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: userMsg,
        config: {
          systemInstruction: `You are LynqSwift, the execution-first AI assistant for LYNQUP. 
          Your personality is technical, elite, and helpful. 
          LYNQUP solves 'Messaging Debt' by replacing fragmented DMs with structured execution.
          KEY CONCEPTS:
          1. The Shelf: Vetted talent roster.
          2. The Engine: Automated GPS verification and Smart-Escrow.
          3. Messaging Debt: The chaos of fragmented WhatsApp/DM coordination.
          Keep responses concise and professional. If users ask about booking, guide them to the 'Shelf'.`,
        },
      });

      const botText = response.text || "Connection timeout. Please retry execution signal.";
      setMessages(prev => [...prev, { role: 'bot', text: botText }]);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'bot', text: "Error in neural link. Please refresh protocol." }]);
    } finally {
      setIsThinking(false);
    }
  };

  return (
    <AnimatePresence>
      {isOpen && (
        <motion.div
          initial={{ opacity: 0, scale: 0.9, y: 20, x: 20 }}
          animate={{ opacity: 1, scale: 1, y: 0, x: 0 }}
          exit={{ opacity: 0, scale: 0.9, y: 20, x: 20 }}
          className="fixed bottom-24 right-6 w-[380px] h-[500px] bg-white/90 backdrop-blur-2xl rounded-[2.5rem] shadow-2xl z-[200] border border-gray-100 flex flex-col overflow-hidden"
        >
