              <div>
                <h4 className="font-bold text-sm text-black">LynqSwift v1.0</h4>
                <p className="text-[9px] text-blue-600 font-bold uppercase tracking-widest flex items-center gap-1">
                  <span className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse" /> Protocol Online
                </p>
              </div>
            </div>
            <button onClick={onClose} className="p-2 hover:bg-gray-100 rounded-full transition-colors text-gray-400">
              <X className="w-5 h-5" />
            </button>
          </div>

          {/* Messages */}
          <div ref={scrollRef} className="flex-grow p-6 overflow-y-auto space-y-4 scrollbar-hide">
            {messages.map((m, i) => (
              <motion.div
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                key={i}
                className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}
              >
                <div className={`max-w-[85%] p-4 rounded-2xl text-sm leading-relaxed ${
                  m.role === 'user' 
                  ? 'bg-black text-white rounded-tr-none' 
                  : 'bg-gray-100 text-gray-800 rounded-tl-none border border-gray-200/50'
                }`}>
                  {m.text}
                </div>
              </motion.div>
            ))}
            {isThinking && (
              <div className="flex justify-start">
                <div className="bg-blue-50 text-blue-600 p-4 rounded-2xl rounded-tl-none border border-blue-100 flex items-center gap-3">
