          </div>

          {/* Quick Actions */}
          {messages.length < 3 && !isThinking && (
            <div className="px-6 pb-2 flex flex-wrap gap-2">
              {["Explain Messaging Debt", "How does GPS work?", "Booking Guide"].map(t => (
                <button 
                  key={t}
                  onClick={() => { setInput(t); }}
                  className="text-[10px] font-bold bg-gray-50 text-gray-500 border border-gray-100 px-3 py-1.5 rounded-lg hover:bg-blue-600 hover:text-white transition-all"
