      className="fixed bottom-4 right-4 w-[180px] h-[180px] z-[250] cursor-pointer group"
      onClick={onToggleChat}
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
    >
      <div className="absolute inset-0 flex items-center justify-center">
        <AnimatePresence>
          {hovered && !isChatOpen && (
            <motion.div 
              initial={{ opacity: 0, scale: 0.8, y: -20 }}
              animate={{ opacity: 1, scale: 1, y: -50 }}
              exit={{ opacity: 0, scale: 0.8, y: -20 }}
              className="absolute bg-white text-black px-4 py-2 rounded-xl text-[10px] font-bold uppercase tracking-widest shadow-xl border border-gray-100 whitespace-nowrap"
            >
              Need help? Click me.
            </motion.div>
          )}
        </AnimatePresence>
      </div>

      <Canvas camera={{ position: [0, 0, 5], fov: 30 }} alpha={true}>
        <ambientLight intensity={1} />
        <pointLight position={[5, 5, 5]} intensity={2} />
        <spotLight position={[0, 10, 0]} angle={0.15} penumbra={1} intensity={2} />
        <LynqSwift isThinking={isThinking} />
      </Canvas>

      {/* Glow Effect */}
      <div className={`absolute inset-10 rounded-full blur-[40px] transition-all duration-500 opacity-20 -z-10 ${isThinking ? 'bg-orange-500' : 'bg-blue-600'}`} />
    </div>
