import React, { useState, useEffect, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { ShoppingBag, X, Check, MapPin, ShieldCheck, RefreshCw, ArrowRight } from 'lucide-react';
import ThreeBackground from './components/ThreeBackground';
import PointerAvatar from './components/PointerAvatar';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import LogicSection from './components/LogicSection';
import ExecutionSteps from './components/ExecutionSteps';
import StoreSection from './components/StoreSection';
import EngineSection from './components/EngineSection';
import ProfileModal from './components/ProfileModal';
import JoinModal from './components/JoinModal';
import RequestPage from './components/RequestPage';
import HelpBot from './components/HelpBot';
import { Creator, AppView } from './types';

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('home');
  const [bag, setBag] = useState<Creator[]>([]);
  const [selectedCreator, setSelectedCreator] = useState<Creator | null>(null);
  const [isJoinModalOpen, setIsJoinModalOpen] = useState(false);

  // Help Bot States
  const [isHelpOpen, setIsHelpOpen] = useState(false);
  const [isThinking, setIsThinking] = useState(false);

  useEffect(() => {
    const savedBag = localStorage.getItem('lynqup_bag');
    if (savedBag) setBag(JSON.parse(savedBag));
  }, []);

  const addToBag = useCallback((creator: Creator) => {
    setBag(prev => {
      if (prev.some(c => c.name === creator.name)) return prev;
      const newBag = [...prev, creator];
      localStorage.setItem('lynqup_bag', JSON.stringify(newBag));
      return newBag;
    });
    setSelectedCreator(null);
  }, []);

  const removeFromBag = useCallback((index: number) => {
    setBag(prev => {
      const newBag = prev.filter((_, i) => i !== index);
      localStorage.setItem('lynqup_bag', JSON.stringify(newBag));
      return newBag;
    });
  }, []);

  const clearBag = useCallback(() => {
    setBag([]);
    localStorage.removeItem('lynqup_bag');
  }, []);

  return (
    <div className="relative min-h-screen bg-black text-white selection:bg-blue-500/30">
      <ThreeBackground />

      <PointerAvatar 
        onToggleChat={() => setIsHelpOpen(!isHelpOpen)} 
        isChatOpen={isHelpOpen}
        isThinking={isThinking}
      />

      <Navbar 
        bagCount={bag.length} 
        onViewChange={setView} 
        onJoinClick={() => setIsJoinModalOpen(true)}
      />

      <AnimatePresence mode="wait">
        {view === 'home' ? (
          <motion.main
            key="home"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="relative z-10"
          >
            <Hero />
            <StoreSection onSelectCreator={setSelectedCreator} />
            <LogicSection />
            <ExecutionSteps />
            <EngineSection />

            <footer className="py-20 text-center text-gray-500 text-[10px] tracking-[0.2em] uppercase">
              © 2024 LYNQUP. Execution through Architecture.
            </footer>
          </motion.main>
        ) : (
          <motion.div
            key="request"
            initial={{ x: '100%' }}
            animate={{ x: 0 }}
            exit={{ x: '100%' }}
            transition={{ type: 'spring', damping: 25, stiffness: 200 }}
            className="relative z-20"
          >
            <RequestPage 
              bag={bag} 
              onRemove={removeFromBag} 
              onSuccess={() => {
                clearBag();
                setView('home');
              }}
            />
          </motion.div>
        )}
      </AnimatePresence>

      <HelpBot 
        isOpen={isHelpOpen} 
        onClose={() => setIsHelpOpen(false)} 
        isThinking={isThinking}
        setIsThinking={setIsThinking}
      />

      <AnimatePresence>
        {selectedCreator && (
          <ProfileModal 
            creator={selectedCreator} 
            onClose={() => setSelectedCreator(null)} 
            onAdd={addToBag}
            isAlreadyInBag={bag.some(c => c.name === selectedCreator.name)}
          />
        )}

        {isJoinModalOpen && (
          <JoinModal onClose={() => setIsJoinModalOpen(false)} />
        )}
      </AnimatePresence>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { X, Send, Zap, Terminal, Cpu, Radio } from 'lucide-react';
import { GoogleGenAI } from "@google/genai";

interface HelpBotProps {
  isOpen: boolean;
  onClose: () => void;
  isThinking: boolean;
  setIsThinking: (v: boolean) => void;
}

const HelpBot: React.FC<HelpBotProps> = ({ isOpen, onClose, isThinking, setIsThinking }) => {
  const [messages, setMessages] = useState<{role: 'user' | 'bot', text: string}[]>([
    { role: 'bot', text: "Protocol initialized. I am LynqSwift. How can I assist your execution today?" }
  ]);
  const [input, setInput] = useState('');
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || isThinking) return;

    const userMsg = input.trim();
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setIsThinking(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: userMsg,
        config: {
          systemInstruction: `You are LynqSwift, the execution-first AI assistant for LYNQUP. 
          Your personality is technical, elite, and helpful. 
          LYNQUP solves 'Messaging Debt' by replacing fragmented DMs with structured execution.
          KEY CONCEPTS:
          1. The Shelf: Vetted talent roster.
          2. The Engine: Automated GPS verification and Smart-Escrow.
          3. Messaging Debt: The chaos of fragmented WhatsApp/DM coordination.
          Keep responses concise and professional. Use technical terminology.`,
        },
      });

      const botText = response.text || "Connection timeout. Please retry execution signal.";
      setMessages(prev => [...prev, { role: 'bot', text: botText }]);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'bot', text: "Error in neural link. Please refresh protocol." }]);
    } finally {
      setIsThinking(false);
    }
  };

  return (
    <AnimatePresence>
      {isOpen && (
        <motion.div
          initial={{ opacity: 0, scale: 0.9, x: 100, y: 50 }}
          animate={{ opacity: 1, scale: 1, x: 0, y: 0 }}
          exit={{ opacity: 0, scale: 0.9, x: 100, y: 50 }}
          transition={{ type: 'spring', damping: 25, stiffness: 200 }}
          className="fixed bottom-32 right-32 w-[360px] h-[520px] bg-white/80 backdrop-blur-3xl rounded-[3rem] shadow-[0_32px_128px_-16px_rgba(0,0,0,0.3)] z-[200] border border-white/50 flex flex-col overflow-hidden"
        >
          {/* HUD Header */}
          <div className="p-6 border-b border-gray-100 flex items-center justify-between bg-white/50">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-black rounded-2xl flex items-center justify-center shadow-lg">
                <Cpu className="w-5 h-5 text-blue-500" />
              </div>
              <div>
                <h4 className="font-bold text-sm text-black tracking-tight">LynqSwift HUD</h4>
                <div className="flex items-center gap-2">
                  <span className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse" />
                  <p className="text-[9px] text-gray-400 font-bold uppercase tracking-widest">Neural Link Active</p>
                </div>
              </div>
            </div>
            <button onClick={onClose} className="p-2 hover:bg-gray-100 rounded-xl transition-colors text-gray-400">
              <X className="w-5 h-5" />
            </button>
          </div>

          {/* Messages */}
          <div ref={scrollRef} className="flex-grow p-6 overflow-y-auto space-y-4 scrollbar-hide">
            {messages.map((m, i) => (
              <motion.div
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                key={i}
                className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}
              >
                <div className={`max-w-[85%] p-4 rounded-2xl text-[13px] leading-relaxed ${
                  m.role === 'user' 
                  ? 'bg-blue-600 text-white rounded-tr-none shadow-lg shadow-blue-500/20' 
                  : 'bg-gray-50 text-gray-800 rounded-tl-none border border-gray-200/50'
                }`}>
                  {m.text}
                </div>
              </motion.div>
            ))}
            {isThinking && (
              <div className="flex justify-start">
                <div className="bg-gray-50 text-blue-600 p-4 rounded-2xl rounded-tl-none border border-gray-100 flex items-center gap-3">
                  <Radio className="w-4 h-4 animate-pulse" />
                  <span className="text-[10px] font-bold tracking-widest uppercase">Streaming Response...</span>
                </div>
              </div>
            )}
          </div>

          {/* Quick Telemetry Chips */}
          <div className="px-6 pb-2 flex flex-wrap gap-2">
            {["Engine Specs", "GPS Protocol", "Pricing Model"].map(t => (
              <button 
                key={t}
                onClick={() => setInput(t)}
                className="text-[9px] font-bold bg-white text-gray-500 border border-gray-100 px-3 py-1.5 rounded-full hover:bg-black hover:text-white transition-all shadow-sm"
              >
                {t}
              </button>
            ))}
          </div>

          {/* Neural Input */}
          <div className="p-6 bg-white/50 border-t border-gray-100">
            <div className="relative flex items-center">
              <input 
                type="text"
                placeholder="Type execution query..."
                className="w-full p-4 bg-white/50 rounded-2xl pr-14 text-sm outline-none focus:ring-2 ring-blue-500/50 transition-all text-black border border-gray-100"
                value={input}
                onChange={e => setInput(e.target.value)}
                onKeyPress={e => e.key === 'Enter' && handleSend()}
              />
              <button 
                onClick={handleSend}
                disabled={isThinking || !input.trim()}
                className="absolute right-2 p-2 bg-black text-white rounded-xl disabled:opacity-30 hover:bg-blue-600 transition-colors shadow-lg"
              >
                <Send className="w-4 h-4" />
              </button>
            </div>
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
};

export default HelpBot;

import React, { useState, useEffect, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
