  const chatRef = useRef<any>(null);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [messages]);

  // Initialize or get the chat instance
  const getChat = () => {
    if (chatRef.current) return chatRef.current;

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    chatRef.current = ai.chats.create({
      model: 'gemini-3-flash-preview',
      config: {
        systemInstruction: `You are LynqSwift, the execution-first AI assistant for LYNQUP. 
        Your personality is technical, elite, and precise. 
        LYNQUP is a platform that solves 'Messaging Debt' by replacing DMs with structured execution.
        CORE SYSTEMS:
        1. The Shelf: Vetted talent (DJs, Creators, Production, Speakers).
        2. The Engine: GPS Verification for on-site talent and Content-Hashing for digital delivery.
        3. Smart-Escrow: Funds are locked and released only upon technical verification.
        4. Unified Brief: One request for a whole roster.
        Respond with concise, high-impact technical advice. Use terms like 'telemetry', 'protocol', 'execution', and 'sync'.`,
      },
    });
    return chatRef.current;
  };

  const handleSend = async (overrideText?: string) => {
    const textToSend = overrideText || input.trim();
    if (!textToSend || isThinking) return;

    setInput('');
    const newMessages = [...messages, { role: 'user' as const, text: textToSend }];
    setMessages(newMessages);
    setIsThinking(true);

    try {
      const chat = getChat();
      // Use streaming for 100% functional modern AI experience
      const streamResponse = await chat.sendMessageStream({ message: textToSend });

      let fullResponse = '';
      // Prepare a slot in messages for the streaming text
      setMessages(prev => [...prev, { role: 'model', text: '' }]);

      for await (const chunk of streamResponse) {
        const c = chunk as GenerateContentResponse;
        const textChunk = c.text || "";
        fullResponse += textChunk;

        setMessages(prev => {
          const updated = [...prev];
          updated[updated.length - 1].text = fullResponse;
          return updated;
        });
      }
    } catch (error) {
      console.error("Link Error:", error);
      setMessages(prev => [...prev, { role: 'model', text: "Signal degradation detected. Please retry execution query." }]);
    } finally {
      setIsThinking(false);
    }
  };

  return (
    <AnimatePresence>
      {isOpen && (
        <motion.div
          initial={{ opacity: 0, scale: 0.9, x: 50, y: 50 }}
          animate={{ opacity: 1, scale: 1, x: 0, y: 0 }}
          exit={{ opacity: 0, scale: 0.9, x: 50, y: 50 }}
          transition={{ type: 'spring', damping: 25, stiffness: 200 }}
          // adjusted right-56 to clear the bird completely
          className="fixed bottom-32 right-56 w-[380px] h-[540px] bg-white/90 backdrop-blur-3xl rounded-[3rem] shadow-[0_32px_128px_-16px_rgba(0,0,0,0.4)] z-[200] border border-white/50 flex flex-col overflow-hidden"
        >
          {/* HUD Header */}
          <div className="p-6 border-b border-gray-100 flex items-center justify-between bg-white/60">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-black rounded-2xl flex items-center justify-center shadow-lg group">
                <Cpu className="w-5 h-5 text-blue-500 group-hover:rotate-90 transition-transform" />
              </div>
              <div>
                <h4 className="font-bold text-sm text-black tracking-tight flex items-center gap-2">
                  LynqSwift v1.2 <Sparkles className="w-3 h-3 text-blue-500" />
                </h4>
                <div className="flex items-center gap-2">
                  <span className={`w-1.5 h-1.5 rounded-full ${isThinking ? 'bg-blue-500 animate-pulse' : 'bg-green-500'}`} />
                  <p className="text-[9px] text-gray-400 font-bold uppercase tracking-widest">
                    {isThinking ? 'Processing Signal' : 'Neural Link Active'}
                  </p>
                </div>
              </div>
            </div>
            <button onClick={onClose} className="p-2 hover:bg-gray-100 rounded-xl transition-colors text-gray-400">
              <X className="w-5 h-5" />
            </button>
          </div>

          {/* Messages */}
          <div ref={scrollRef} className="flex-grow p-6 overflow-y-auto space-y-6 scrollbar-hide bg-gradient-to-b from-white/0 to-gray-50/50">
            {messages.map((m, i) => (
              <motion.div
                initial={{ opacity: 0, y: 10, scale: 0.95 }}
                animate={{ opacity: 1, y: 0, scale: 1 }}
                key={i}
                className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}
              >
                <div className={`max-w-[85%] p-4 rounded-[1.5rem] text-[13px] leading-relaxed shadow-sm ${
                  m.role === 'user' 
                  ? 'bg-black text-white rounded-tr-none' 
                  : 'bg-white text-gray-800 rounded-tl-none border border-gray-100'
                }`}>
                  {m.text}
                </div>
              </motion.div>
            ))}
            {isThinking && messages[messages.length-1].text === '' && (
              <div className="flex justify-start">
                <div className="bg-blue-50 text-blue-600 p-4 rounded-2xl rounded-tl-none border border-blue-100 flex items-center gap-3">
                  <Radio className="w-4 h-4 animate-pulse" />
                  <span className="text-[10px] font-bold tracking-widest uppercase">Capturing Packets...</span>
                </div>
              </div>
            )}
          </div>

          {/* Telemetry Chips */}
          <div className="px-6 pb-2 flex flex-wrap gap-2">
            {[ "GPS Verification", "Escrow Safety", "Messaging Debt" ].map(t => (
              <button 
                key={t}
                onClick={() => handleSend(t)}
                className="text-[9px] font-bold bg-white text-gray-400 border border-gray-100 px-3 py-2 rounded-full hover:bg-blue-600 hover:text-white hover:border-blue-600 transition-all shadow-sm"
              >
                {t}
              </button>
            ))}
          </div>

          {/* Input */}
          <div className="p-6 bg-white border-t border-gray-100">
            <div className="relative flex items-center">
              <input 
                type="text"
                placeholder="Query execution protocol..."
                className="w-full p-4 bg-gray-50 rounded-2xl pr-14 text-sm outline-none focus:ring-2 ring-blue-500 transition-all text-black border border-gray-100"
                value={input}
                onChange={e => setInput(e.target.value)}
                onKeyPress={e => e.key === 'Enter' && handleSend()}
              />
              <button 
                onClick={() => handleSend()}
                disabled={isThinking || !input.trim()}
                className="absolute right-2 p-2.5 bg-black text-white rounded-xl disabled:opacity-30 hover:bg-blue-600 transition-colors shadow-lg"
              >
                <Send className="w-4 h-4" />
              </button>
            </div>
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
};

export default HelpBot;

import React, { useState, useEffect, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
