    setLoading(true);
    try {
      const data = {
        ...formData,
        talent_names: bag.map(t => t.name).join(', '),
        status: 'pending'
      };

      const { error } = await supabase.from('event_requests').insert([data]);
      if (error) throw error;

      setIsSuccess(true);
      setTimeout(() => {
        onSuccess();
      }, 3000);
    } catch (err: any) {
      alert(`System Fault: ${err.message}`);
    } finally {
      setLoading(false);
    }
  };

