class SoundEngine {
  private ctx: AudioContext | null = null;
  private enabled: boolean = true;

  private init() {
    if (!this.ctx) {
      this.ctx = new (window.AudioContext || (window as any).webkitAudioContext)({
        sampleRate: 44100
      });
    }
    if (this.ctx.state === 'suspended') {
      this.ctx.resume().catch(console.error);
    }
  }

  setEnabled(val: boolean) {
    this.enabled = val;
    if (val) this.init();
  }

  isEnabled() {
    return this.enabled;
  }

  private playTone(freq: number, type: OscillatorType, duration: number, volume: number) {
    if (!this.enabled) return;
    this.init();

    if (!this.ctx || this.ctx.state === 'suspended') return;

    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();

    osc.type = type;
    osc.frequency.setValueAtTime(freq, this.ctx.currentTime);

    gain.gain.setValueAtTime(volume, this.ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.0001, this.ctx.currentTime + duration);

    osc.connect(gain);
    gain.connect(this.ctx.destination);

    osc.start();
    osc.stop(this.ctx.currentTime + duration);
  }

  // Quick tactile feedback for buttons
  tick() {
    this.playTone(800, 'sine', 0.1, 0.05);
  }

  // Adding something to the roster
  success() {
    this.playTone(400, 'sine', 0.3, 0.1);
    setTimeout(() => this.playTone(600, 'sine', 0.4, 0.08), 50);
  }

  // AI Typing "chatter"
  chatter() {
    const freqs = [1200, 1500, 1800, 2000];
    const freq = freqs[Math.floor(Math.random() * freqs.length)];
    this.playTone(freq, 'sine', 0.05, 0.01);
  }

  // GPS scanning pulse
  ping(pitchShift: number = 0) {
    this.playTone(200 + pitchShift, 'sine', 0.2, 0.05);
  }

  // Error/Alert
  error() {
    this.playTone(150, 'square', 0.3, 0.05);
  }
}

export const sound = new SoundEngine();

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { X, Send, Zap, Terminal, Cpu, Radio, Sparkles } from 'lucide-react';
import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { sound } from '../services/sound';

interface HelpBotProps {
  isOpen: boolean;
  onClose: () => void;
  isThinking: boolean;
  setIsThinking: (v: boolean) => void;
}

const TypewriterText: React.FC<{ text: string; isStreaming?: boolean }> = ({ text, isStreaming }) => {
  const [displayedText, setDisplayedText] = useState("");
  const [isTyping, setIsTyping] = useState(false);
  const fullTextRef = useRef(text);

  useEffect(() => {
    fullTextRef.current = text;
    if (text.length > displayedText.length) {
      setIsTyping(true);
      const timer = setTimeout(() => {
        const nextCharCount = Math.min(displayedText.length + 2, text.length);
        setDisplayedText(text.slice(0, nextCharCount));

        if (displayedText.length % 4 === 0) {
          sound.chatter();
        }
      }, 10);
      return () => clearTimeout(timer);
    } else {
      setIsTyping(false);
    }
  }, [text, displayedText]);

  return (
    <div className="relative">
      <span className="whitespace-pre-wrap">{displayedText}</span>
      {isStreaming && isTyping && (
        <motion.span
          animate={{ opacity: [0, 1, 0] }}
          transition={{ repeat: Infinity, duration: 0.8 }}
          className="inline-block w-1.5 h-4 ml-1 bg-blue-500 translate-y-0.5"
        />
      )}
    </div>
  );
};

const HelpBot: React.FC<HelpBotProps> = ({ isOpen, onClose, isThinking, setIsThinking }) => {
  const [messages, setMessages] = useState<{role: 'user' | 'model', text: string}[]>([
    { role: 'model', text: "Protocol initialized. I am LynqSwift. How can I assist your Indian event execution today? ⚡" }
  ]);
  const [input, setInput] = useState('');
  const scrollRef = useRef<HTMLDivElement>(null);

  const chatRef = useRef<any>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({
        top: scrollRef.current.scrollHeight,
        behavior: 'smooth'
      });
    }
  }, [messages]);

  const getChat = () => {
    if (chatRef.current) return chatRef.current;

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    chatRef.current = ai.chats.create({
      model: 'gemini-3-flash-preview',
      config: {
        systemInstruction: `You are LynqSwift, the execution-first AI assistant for LYNQUP. 
        Your personality is technical, elite, and precise. 
        LYNQUP is a platform for the Indian event market that solves 'Messaging Debt' by replacing DMs with structured execution.

        FORMATTING RULES:
        1. DO NOT use asterisks (*) for bolding or lists. Provide clean plain text.
        2. DO NOT use markdown headers or bold symbols.
        3. ALWAYS use relevant emojis to enhance the tech-forward personality (e.g., ⚡, 🛰️, 🛡️, 🔗, ⚙️).

        CORE SYSTEMS:
        - The Shelf: Vetted talent nodes (DJs, Creators, Production, Speakers) priced in Indian Rupees (₹).
        - The Engine: GPS Verification for site-sync and Content-Hashing for digital delivery.
        - Smart-Escrow: Capital in INR is secured and released only via technical validation.
        - Unified Brief: A single sync-point for entire rosters.

        Respond with concise, high-impact technical advice. Use terms like 'telemetry', 'protocol', 'execution', and 'sync'. Mention Indian Rupees (₹) where relevant.`,
      },
    });
    return chatRef.current;
  };

  const handleSend = async (overrideText?: string) => {
    const textToSend = overrideText || input.trim();
    if (!textToSend || isThinking) return;

    sound.tick();
    setInput('');
    const userMessage = { role: 'user' as const, text: textToSend };
    setMessages(prev => [...prev, userMessage]);
    setIsThinking(true);

    try {
      const chat = getChat();
      const streamResponse = await chat.sendMessageStream({ message: textToSend });

      let fullResponse = '';
      setMessages(prev => [...prev, { role: 'model', text: '' }]);

      for await (const chunk of streamResponse) {
        const c = chunk as GenerateContentResponse;
        const textChunk = c.text || "";
        fullResponse += textChunk;

        setMessages(prev => {
          const updated = [...prev];
          updated[updated.length - 1] = { role: 'model', text: fullResponse };
          return updated;
        });
      }
    } catch (error) {
      sound.error();
      setMessages(prev => [...prev, { role: 'model', text: "Signal degradation detected. Please retry execution query. ⚠️" }]);
    } finally {
      setIsThinking(false);
    }
  };

  return (
    <AnimatePresence>
      {isOpen && (
        <motion.div
          initial={{ opacity: 0, scale: 0.9, x: 50, y: 50 }}
          animate={{ opacity: 1, scale: 1, x: 0, y: 0 }}
          exit={{ opacity: 0, scale: 0.9, x: 50, y: 50 }}
          transition={{ type: 'spring', damping: 25, stiffness: 200 }}
          className="fixed bottom-32 right-56 w-[400px] h-[580px] bg-white/95 backdrop-blur-3xl rounded-[3rem] shadow-[0_32px_128px_-16px_rgba(0,0,0,0.5)] z-[200] border border-white/50 flex flex-col overflow-hidden"
        >
          <div className="p-6 border-b border-gray-100 flex items-center justify-between bg-white/60">
            <div className="flex items-center gap-4">
              <div className="w-12 h-12 bg-black rounded-2xl flex items-center justify-center shadow-lg group">
                <Cpu className="w-6 h-6 text-blue-500 group-hover:rotate-90 transition-transform duration-500" />
              </div>
              <div>
                <h4 className="font-bold text-base text-black tracking-tight flex items-center gap-2">
                  LynqSwift v1.2 <Sparkles className="w-4 h-4 text-blue-500" />
                </h4>
                <div className="flex items-center gap-2">
                  <span className={`w-1.5 h-1.5 rounded-full ${isThinking ? 'bg-blue-500 animate-pulse' : 'bg-green-500'}`} />
                  <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">
                    {isThinking ? 'Processing Signal' : 'Neural Link Active'}
                  </p>
                </div>
              </div>
            </div>
            <button onClick={() => { sound.tick(); onClose(); }} className="p-2 hover:bg-gray-100 rounded-2xl transition-all text-gray-400 hover:text-black">
              <X className="w-6 h-6" />
            </button>
          </div>

          <div ref={scrollRef} className="flex-grow p-6 overflow-y-auto space-y-6 scrollbar-hide bg-gradient-to-b from-white/0 to-gray-50/50">
            {messages.map((m, i) => (
              <motion.div
                initial={{ opacity: 0, y: 15, scale: 0.98 }}
                animate={{ opacity: 1, y: 0, scale: 1 }}
                key={i}
                className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}
              >
                <div className={`max-w-[90%] p-5 rounded-[1.8rem] text-[14px] leading-relaxed shadow-sm transition-all ${
                  m.role === 'user' 
                  ? 'bg-black text-white rounded-tr-none' 
                  : 'bg-white text-gray-800 rounded-tl-none border border-gray-100 shadow-xl shadow-gray-200/20'
                }`}>
                  {m.role === 'model' ? (
                    <TypewriterText text={m.text} isStreaming={isThinking && i === messages.length - 1} />
                  ) : (
                    <span className="whitespace-pre-wrap">{m.text}</span>
                  )}
                </div>
              </motion.div>
            ))}
            {isThinking && messages[messages.length-1].text === '' && (
              <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex justify-start">
                <div className="bg-blue-50 text-blue-600 p-5 rounded-[1.8rem] rounded-tl-none border border-blue-100 flex items-center gap-3">
                  <Radio className="w-5 h-5 animate-pulse" />
                  <span className="text-[11px] font-bold tracking-[0.2em] uppercase">Securing Uplink...</span>
                </div>
              </motion.div>
            )}
          </div>

          <div className="px-6 pb-4 flex flex-wrap gap-2">
            {[ "GPS Workflow", "₹ Escrow Protocol", "Messaging Debt" ].map(t => (
              <motion.button 
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
                key={t}
                onClick={() => handleSend(t)}
                className="text-[10px] font-bold bg-white text-gray-500 border border-gray-100 px-4 py-2 rounded-full hover:bg-blue-600 hover:text-white hover:border-blue-600 transition-all shadow-sm flex items-center gap-2"
              >
                <Zap className="w-3 h-3" /> {t}
              </motion.button>
            ))}
          </div>

          <div className="p-6 bg-white border-t border-gray-100">
            <div className="relative flex items-center gap-3">
              <div className="relative flex-grow">
                <input 
                  type="text"
                  placeholder="Initiate execution query..."
                  className="w-full p-5 bg-gray-50 rounded-[1.5rem] pr-14 text-sm outline-none focus:ring-2 ring-blue-500/50 transition-all text-black border border-gray-100 placeholder:text-gray-400"
                  value={input}
                  onChange={e => setInput(e.target.value)}
                  onKeyPress={e => e.key === 'Enter' && handleSend()}
                />
                <button 
                  onClick={() => handleSend()}
                  disabled={isThinking || !input.trim()}
                  className="absolute right-2 top-1/2 -translate-y-1/2 p-3 bg-black text-white rounded-[1.2rem] disabled:opacity-30 hover:bg-blue-600 transition-all shadow-lg active:scale-95"
                >
                  <Send className="w-5 h-5" />
                </button>
              </div>
            </div>
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
};

export default HelpBot;

import React, { useRef, useState, useMemo } from 'react';
import { Canvas, useFrame, useThree } from '@react-three/fiber';
import * as THREE from 'three';
import { motion, AnimatePresence } from 'framer-motion';

interface LynqSwiftProps {
  isThinking: boolean;
}

const LynqSwift: React.FC<LynqSwiftProps> = ({ isThinking }) => {
  const groupRef = useRef<THREE.Group>(null!);
  const headRef = useRef<THREE.Group>(null!);
  const leftWingRef = useRef<THREE.Mesh>(null!);
  const rightWingRef = useRef<THREE.Mesh>(null!);
  const { mouse } = useThree();
  const [blink, setBlink] = useState(false);

  const birdMaterial = useMemo(() => new THREE.MeshPhysicalMaterial({
    color: "#ffffff",
    metalness: 0.1,
    roughness: 0.2,
    clearcoat: 1,
    clearcoatRoughness: 0.1,
    sheen: 1,
    sheenColor: "#0071e3",
    sheenRoughness: 0.5
  }), []);

  const accentMaterial = useMemo(() => new THREE.MeshStandardMaterial({
    color: "#0071e3",
    emissive: "#0071e3",
    emissiveIntensity: 2
  }), []);

  useFrame((state) => {
    const t = state.clock.getElapsedTime();

    groupRef.current.position.y = Math.sin(t * 2) * 0.1 + (isThinking ? Math.sin(t * 10) * 0.05 : 0);

    const targetRotX = -mouse.y * 0.5;
    const targetRotY = mouse.x * 0.8;
    headRef.current.rotation.x = THREE.MathUtils.lerp(headRef.current.rotation.x, targetRotX, 0.15);
    headRef.current.rotation.y = THREE.MathUtils.lerp(headRef.current.rotation.y, targetRotY, 0.15);

    const baseFlap = 2 + (Math.abs(mouse.x) + Math.abs(mouse.y)) * 5;
    const flapSpeed = isThinking ? 15 : baseFlap;
    const flapAngle = Math.sin(t * flapSpeed) * 0.4;

    if (leftWingRef.current && rightWingRef.current) {
      leftWingRef.current.rotation.z = 0.5 + flapAngle;
      rightWingRef.current.rotation.z = -0.5 - flapAngle;
    }

    if (Math.random() < 0.01 && !blink) {
      setBlink(true);
      setTimeout(() => setBlink(false), 100);
    }
  });

  return (
    <group ref={groupRef}>
      <mesh rotation={[Math.PI / 6, 0, 0]}>
        <sphereGeometry args={[0.7, 32, 32]} />
        <primitive object={birdMaterial} attach="material" />
      </mesh>
      <mesh position={[0, -0.4, -0.6]} rotation={[Math.PI / 4, 0, 0]}>
        <coneGeometry args={[0.3, 0.8, 4]} />
        <primitive object={birdMaterial} attach="material" />
      </mesh>
      <mesh ref={leftWingRef} position={[-0.6, 0.2, 0]} rotation={[0, 0, 0.5]}>
        <boxGeometry args={[1.2, 0.05, 0.5]} />
        <primitive object={birdMaterial} attach="material" />
      </mesh>
      <mesh ref={rightWingRef} position={[0.6, 0.2, 0]} rotation={[0, 0, -0.5]}>
        <boxGeometry args={[1.2, 0.05, 0.5]} />
        <primitive object={birdMaterial} attach="material" />
      </mesh>
      <group ref={headRef} position={[0, 0.5, 0.4]}>
        <mesh>
          <sphereGeometry args={[0.45, 32, 32]} />
          <primitive object={birdMaterial} attach="material" />
        </mesh>
        <mesh position={[0, -0.1, 0.45]} rotation={[Math.PI / 2, 0, 0]}>
          <coneGeometry args={[0.1, 0.3, 4]} />
          <primitive object={accentMaterial} attach="material" />
        </mesh>
        <group position={[0, 0.1, 0.38]}>
          <mesh position={[-0.18, 0, 0]} scale={[1, blink ? 0.1 : 1, 1]}>
            <sphereGeometry args={[0.04, 16, 16]} />
            <meshStandardMaterial color="#000000" />
          </mesh>
          <mesh position={[0.18, 0, 0]} scale={[1, blink ? 0.1 : 1, 1]}>
            <sphereGeometry args={[0.04, 16, 16]} />
            <meshStandardMaterial color="#000000" />
          </mesh>
        </group>
      </group>
      <pointLight intensity={1} color="#0071e3" distance={3} />
    </group>
  );
};

